#!/usr/bin/env python3
import hashlib, html, json, runpy, time
from pathlib import Path
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260830_1000.py')),run_name='recipe_base')
TITLE='Hambúrguer de Grão-de-Bico Macio para Bebê: Receita Assada com Cenoura'; SLUG_KEY='hamburguer-grao-de-bico-macio-bebe'; CLUSTER='Cluster 5 — Refeições com feijão, lentilha, grão-de-bico e outras leguminosas'; KEYWORD='hambúrguer de grão-de-bico macio para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']
def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Hambúrguer caseiro de grão-de-bico com cenoura e aveia, assado e com textura macia para alimentação complementar.','recipeCategory':'Almoço e jantar','recipeCuisine':'Brasileira','keywords':KEYWORD+', alimentação complementar, grão-de-bico, leguminosas','recipeYield':'6 hambúrgueres pequenos','recipeIngredient':['1 xícara de grão-de-bico cozido e bem escorrido','2 colheres (sopa) de cenoura ralada fina','2 colheres (sopa) de aveia em flocos finos','1 colher (sopa) de cebola bem picada'],'recipeInstructions':[{'@type':'HowToStep','text':'Amasse o grão-de-bico cozido com um garfo até formar uma massa ainda com alguma textura.'},{'@type':'HowToStep','text':'Misture cenoura, aveia e cebola até a massa manter o formato sem ficar seca.'},{'@type':'HowToStep','text':'Modele discos pequenos e grossos e asse a 200 °C apenas até firmarem, sem formar crosta dura.'},{'@type':'HowToStep','text':'Espere amornar e adapte o formato às habilidades da criança antes de servir.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Este hambúrguer de grão-de-bico é uma preparação caseira assada, feita com poucos ingredientes e pensada para ficar macia por dentro. A proposta é variar a forma de servir leguminosas sem depender de hambúrguer pronto ou de uma textura crocante.</p><p><strong>Atenção:</strong> adapte tamanho, formato e textura às habilidades da criança e ofereça sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação ou deglutição e necessidades especiais exigem avaliação profissional individualizada.</p><h2>Ingredientes</h2><ul><li>1 xícara de grão-de-bico cozido e bem escorrido</li><li>2 colheres (sopa) de cenoura ralada fina</li><li>2 colheres (sopa) de aveia em flocos finos</li><li>1 colher (sopa) de cebola bem picada</li></ul><h2>Modo de preparo</h2><ol><li>Preaqueça o forno a 200 °C.</li><li>Amasse o grão-de-bico cozido com um garfo. Deixe a massa uniforme o suficiente para modelar, mas não precisa virar um purê totalmente liso.</li><li>Misture a cenoura, a aveia e a cebola. A massa deve ficar úmida e manter o formato quando pressionada.</li><li>Modele discos pequenos e mais grossos. Evite deixá-los muito finos, porque podem ressecar.</li><li>Disponha em assadeira e asse somente até ficarem firmes e cozidos, sem esperar formar uma casca dura.</li><li>Espere amornar antes de servir.</li></ol><h2>Como deve ficar a textura</h2><p>O hambúrguer pronto deve ceder facilmente quando pressionado com um garfo e se desfazer sem exigir muita força. Se a massa estiver quebradiça antes de assar, amasse um pouco mais o grão-de-bico; se estiver muito úmida, acrescente aveia aos poucos.</p><h2>Como servir e adaptar</h2><p>O formato precisa acompanhar as habilidades da criança. Pode ser oferecido em um pedaço que ela consiga manejar ou desmanchado com o garfo. O Ministério da Saúde orienta a inclusão de alimentos in natura ou minimamente processados a partir dos 6 meses e a evolução gradual da consistência conforme a criança desenvolve habilidades para comer.</p><h2>Grão-de-bico é uma leguminosa?</h2><p>Sim. O Guia Alimentar para Crianças Brasileiras Menores de 2 Anos inclui o grão-de-bico no grupo dos feijões, junto com lentilha, ervilha e diferentes tipos de feijão. Nesta receita, ele aparece em formato assado e macio, diferente das preparações de colher.</p><h2>Substituições culinárias</h2><p>A cenoura pode ser substituída por abobrinha ralada e bem espremida; nesse caso, ajuste a aveia porque a umidade muda. Para alergias ou necessidades alimentares específicas, procure profissional habilitado em vez de improvisar substituições.</p><h2>Armazenamento</h2><p>Prepare com utensílios limpos e ingredientes corretamente conservados. Não guarde novamente a porção que já teve contato com a boca ou com utensílio usado durante a refeição. Para sobras, siga orientações oficiais de higiene, refrigeração e reaquecimento adequadas às condições da sua casa.</p><h2>Perguntas frequentes</h2><h3>Precisa colocar ovo?</h3><p>Não nesta versão. O grão-de-bico amassado e a aveia ajudam a dar liga. A quantidade de aveia pode variar conforme a umidade do grão cozido.</p><h3>Posso usar grão-de-bico de lata?</h3><p>Para manter a proposta simples, prefira grão-de-bico cozido em casa. Se usar outro produto, confira cuidadosamente a lista de ingredientes e a quantidade de sódio antes de decidir oferecê-lo.</p><h3>Ele deve ficar crocante?</h3><p>Não. O objetivo desta receita é uma textura macia e fácil de desfazer com o garfo, e não uma crosta rígida.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/bolinho-de-lentilha-assado-para-bebe.html'>Bolinho de Lentilha Assado para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/creme-de-lentilha-com-legumes-para-bebe.html'>Creme de Lentilha com Legumes para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/palitinhos-de-legumes-assados-para-bebe.html'>Palitinhos de Legumes Assados para Bebê</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-brasil/eu-quero-me-alimentar-melhor/Documentos/pdf/guia-alimentar-para-criancas-brasileiras-menores-de-2-anos.pdf/' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><h2>Conclusão</h2><p>O hambúrguer caseiro de grão-de-bico amplia as formas de servir leguminosas com uma preparação assada e macia. O ponto mais importante é evitar ressecar e adaptar o formato e a consistência às habilidades da criança.</p><script type='application/ld+json'>{sj}</script>"""
def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('hambúrguer' in t and 'grão-de-bico' in t) or ('hamburguer' in t and 'grao-de-bico' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for chickpea patties'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists():
  original=base['TITLE']; base['TITLE']=TITLE
  try: base['generate_cover'](cp)
  finally: base['TITLE']=original
  base['git_commit_push']([cp],'Add unique AI food photo for soft chickpea patties'); time.sleep(8)
 content=article(cu)
 if MARKER not in content or cu not in content: raise RuntimeError('cover verification failed before publish')
 created=base['api'](tok,'POST',f'/blogs/{BLOG_ID}/posts',{'isDraft':'false','fetchBody':'true'},{'kind':'blogger#post','blog':{'id':BLOG_ID},'title':TITLE,'content':content,'labels':['Alimentação complementar','Almoço','Jantar','Grão-de-bico','Leguminosas']}); pid=str(created.get('id','')); url=created.get('url','')
 if not pid: raise RuntimeError('Blogger did not return post id')
 vc=(base['api'](tok,'GET',f'/blogs/{BLOG_ID}/posts/{pid}',{'view':'ADMIN'}).get('content') or '')
 if MARKER not in vc or cu not in vc: raise RuntimeError('live Blogger post failed cover verification')
 log=base['load_log'](); log.append({'published_at':created.get('published'),'title':TITLE,'url':url,'post_id':pid,'cluster':CLUSTER,'keyword':KEYWORD,'cover_url':cu,'marker':MARKER}); LOG_PATH.write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); RESULT_PATH.write_text('outcome=success\n'+f'title={TITLE}\nurl={url}\npost_id={pid}\ncluster={CLUSTER}\ncover_url={cu}\nmarker_verified=true\n',encoding='utf-8'); base['git_commit_push']([LOG_PATH,RESULT_PATH],'Record published soft chickpea patty recipe')
if __name__=='__main__': main()
